// lib
using MessagePack;

namespace Lib
{
    // Not a [MessagePackObject] itself, so the analyzer does not flag it while building lib.
    // Its members reach the app only as metadata (no DeclaringSyntaxReferences).
    public class BaseModel
    {
        [Key("name")]
        public string Name { get; set; }

        // Int key after a string key: isIntKey is false and stringKey is null -> MsgPack005
        [Key(1)]
        public int Value { get; set; }
    }
}

// app
using MessagePack;
using Lib;

namespace App
{
    [MessagePackObject]
    public class Derived : BaseModel
    {
    }

    public static class Program
    {
        public static void Main()
        {
            var bytes = MessagePackSerializer.Serialize(new Derived { Name = "a", Value = 1 });
            System.Console.WriteLine(bytes.Length);
        }
    }
}
